from openpyxl import load_workbook
from openpyxl.styles import Font, Alignment, Border, Side, PatternFill
from openpyxl.utils import get_column_letter
import copy

def merge_rows_based_on_column(file_path, sheet_name, reference_col, output_sheet_name):
    # Load the workbook and select the sheets
    wb = load_workbook(file_path)
    data_sheet = wb[sheet_name]
    combined_sheet = wb[output_sheet_name]

    # Clear the combined sheet
    combined_sheet.delete_rows(1, combined_sheet.max_row)

    # Copy the header row
    for col in range(1, data_sheet.max_column + 1):
        combined_sheet.cell(row=1, column=col, value=data_sheet.cell(row=1, column=col).value)

    # Dictionary to store grouped rows
    grouped_data = {}

    # Iterate through the data rows
    for row in data_sheet.iter_rows(min_row=2, values_only=False):
        key_value = row[reference_col - 1].value  # Use 1-based index for column
        if key_value not in grouped_data:
            grouped_data[key_value] = {
                'row': [cell.value for cell in row],
                'styles': [copy.copy(cell) for cell in row]
            }
        else:
            # Merge the values for the same key
            for i in range(len(row)):
                if row[i].value is not None:
                    grouped_data[key_value]['row'][i] = row[i].value

    # Write the merged data to the combined sheet
    for idx, (key, data) in enumerate(grouped_data.items()):
        row_data = data['row']
        for col_idx, value in enumerate(row_data):
            cell = combined_sheet.cell(row=idx + 2, column=col_idx + 1, value=value)

            # Apply formatting from the original row
            original_cell = data['styles'][col_idx]
            if original_cell.font:
                cell.font = copy.copy(original_cell.font)
            if original_cell.alignment:
                cell.alignment = copy.copy(original_cell.alignment)
            if original_cell.border:
                cell.border = copy.copy(original_cell.border)
            if original_cell.fill:
                cell.fill = copy.copy(original_cell.fill)

    # Format the numeric values in columns I:R with 2 decimals, no commas, and 0s as blanks
    for row in combined_sheet.iter_rows(min_row=2, max_col=18, max_row=combined_sheet.max_row):
        for cell in row[8:]:  # Columns I to R (index 8 to 17)
            if cell.value is not None:
                try:
                    # Convert to float and format
                    formatted_value = "{:.2f}".format(float(cell.value))
                    # Replace .00 with empty string if needed
                    if formatted_value == "0.00":
                        cell.value = ""
                    else:
                        cell.value = formatted_value
                except (ValueError, TypeError):
                    # If not a number, leave as is
                    pass

    # Save the workbook
    wb.save("output.xlsx")

# Run the function with the specified parameters
merge_rows_based_on_column("input.xlsx", "DATA", 8, "combined")
