from openpyxl import load_workbook

# Load the workbook and select the sheet
wb = load_workbook("input.xlsx")
ws = wb["Sheet1"]

# Dictionary to hold the sum for each letter
letter_sums = {}

# Iterate over the rows in the data table (rows 3 to 9)
for row in ws.iter_rows(min_row=3, max_row=9, min_col=3, max_col=9):
    for cell in row:
        # Check if the cell contains a value
        if cell.value:
            # Extract the letter and number from the cell value
            # Assuming the format is like "A2", "B1", etc.
            if len(cell.value) >= 2:
                letter = cell.value[0]
                number = cell.value[1:]
                try:
                    # Convert the number part to an integer
                    num = int(number)
                    # Add the number to the corresponding letter's sum
                    if letter in letter_sums:
                        letter_sums[letter] += num
                    else:
                        letter_sums[letter] = num
                except ValueError:
                    # Handle cases where the number part is not a valid integer
                    pass

# Write the computed sums to the result range (B11:B17)
for i, row in enumerate(range(11, 18)):
    letter = ws[f"A{row}"].value
    if letter in letter_sums:
        ws[f"B{row}"].value = letter_sums[letter]
    else:
        ws[f"B{row}"].value = 0

# Save the workbook as output.xlsx
wb.save("output.xlsx")
